const input = $('When Executed by Another Workflow').first().json;

// Results from both Databricks queries
const rows_a = $('Collect Product A').first().json.rows_a;

const rows_b = $input.all()
  .map(item => item.json)
  .filter(row => row.sku != null);

// Country and currency
const country = String(input.country || 'IN').trim().toUpperCase();
const currency = country === 'AE' ? 'AED' : 'INR';

// Find exact match, otherwise choose if only one result
function pick(rows, term) {
  const t = String(term).trim().toLowerCase();

  const exact = rows.filter(r =>
    String(r.sku).toLowerCase() === t ||
    String(r.name).toLowerCase() === t
  );

  if (exact.length === 1) return exact[0];
  if (rows.length === 1) return rows[0];
  return null;
}

let result = {
  found: false,
  ambiguous: false,
  message: '',
  currency,
  product_a: '',
  product_b: '',
  price_a: 0,
  price_b: 0,
  price_difference: 0,
  cheaper: '',
  comparison_text: ''
};

if (!['IN', 'AE'].includes(country)) {
  result.message = 'Please provide country IN or AE';
}
else if (!rows_a.length || !rows_b.length) {
  result.message = 'Could not find: ' +
    [
      !rows_a.length ? input.product_a : null,
      !rows_b.length ? input.product_b : null
    ].filter(Boolean).join(', ');
}
else {
  const a = pick(rows_a, input.product_a);
  const b = pick(rows_b, input.product_b);

  if (!a || !b) {
    result.found = true;
    result.ambiguous = true;
    result.message = 'Please clarify: ' +
      [
        !a ? rows_a.map(r => r.name).join(', ') : null,
        !b ? rows_b.map(r => r.name).join(', ') : null
      ].filter(Boolean).join(' / ');
  }
  else {
    function price(row) {
      const rawPrice = country === 'AE'
        ? row.price_aed : row.price_inr;

      const base = Number(rawPrice);
      const discount = Number(row.active_discount_percent);

      if (rawPrice == null || row.active_discount_percent == null ||
          !Number.isFinite(base) || !Number.isFinite(discount) ||
          base < 0 || discount < 0 || discount > 100) {
        throw new Error('Invalid pricing data for ' + row.name);
      }

      return Math.round(base * (100 - discount) / 100);
    }

    const pa = price(a);
    const pb = price(b);

    result = {
      found: true,
      ambiguous: false,
      message: 'OK',
      currency,
      product_a: a.name,
      product_b: b.name,
      price_a: pa,
      price_b: pb,
      price_difference: Math.abs(pa - pb),
      cheaper: pa === pb ? 'same price'
        : pa < pb ? a.name : b.name,
      comparison_text: [
        `${a.name} | ${b.name}`,
        `Price: ${currency} ${pa} | ${currency} ${pb}`,
        `Movement: ${a.movement} | ${b.movement}`,
        `Material: ${a.material} | ${b.material}`,
        `Water resistance: ${a.water_resistance_m} m | ${b.water_resistance_m} m`,
        `Warranty: ${a.warranty_months} months | ${b.warranty_months} months`,
        `Stock: ${a.stock} | ${b.stock}`
      ].join('\n')
    };
  }
}

return [{ json: result }];
